import { readFileSync, statSync } from "node:fs";
import type { ServerOptions } from "node:https";

/** Explicit server-only TLS files; no certificates are generated by Vite. */
export function httpsConfig(
  env: Readonly<Record<string, string | undefined>>,
): ServerOptions | undefined {
  const certFile = env.GODSEYE_TLS_CERT_FILE;
  const keyFile = env.GODSEYE_TLS_KEY_FILE;
  if (!!certFile !== !!keyFile)
    throw Error(
      "Configure both GODSEYE_TLS_CERT_FILE and GODSEYE_TLS_KEY_FILE, or neither",
    );
  if (!certFile || !keyFile) return undefined;

  const read = (path: string, name: string): Buffer => {
    try {
      if (!statSync(path).isFile()) throw Error("Not a regular file");
      return readFileSync(path);
    } catch {
      // Report the setting to fix without logging private key bytes or paths.
      throw Error(`${name} must point to a readable regular TLS file`);
    }
  };
  return {
    cert: read(certFile, "GODSEYE_TLS_CERT_FILE"),
    key: read(keyFile, "GODSEYE_TLS_KEY_FILE"),
  };
}
